INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6583322, 980902, 30982, '<td valign="top">This really stands out to me, Robert.  What a wonderful story it tells.  Processed perfectly!</td>', 'This really stands out to me, Robert.  What a wonderful story it tells.  Processed perfectly!', '2011-11-02 23:20:31.000000', NULL, 1),
(6583331, 980620, 30982, '<td valign="top">Ah!!  A fine collection of notes, tones, lines, curves, colors and shapes.</td>', 'Ah!!  A fine collection of notes, tones, lines, curves, colors and shapes.', '2011-11-02 23:25:58.000000', NULL, 1),
(6583333, 978315, 65234, '<td valign="top">I didn''t know whales had multicolored insides!  I learn so much from other people''s photos ;-)</td>', 'I didn''t know whales had multicolored insides!  I learn so much from other people''s photos ;-)', '2011-11-02 23:26:27.000000', NULL, 1),
(6583335, 978726, 30982, '<td valign="top">Souless, almost evil.  Nice use of grain!</td>', 'Souless, almost evil.  Nice use of grain!', '2011-11-02 23:27:26.000000', NULL, 1),
(6583347, 980327, 65234, '<td valign="top">That''s an AMAZING capture!  That pose is just stunning.  I think I''m in love :-)</td>', 'That''s an AMAZING capture!  That pose is just stunning.  I think I''m in love :-)', '2011-11-02 23:34:08.000000', NULL, 1),
(6583357, 979643, 65234, '<td valign="top">Not looking all that graceful ;-)</td>', 'Not looking all that graceful ;-)', '2011-11-02 23:47:42.000000', NULL, 1),
(6583360, 980805, 30982, '<td valign="top">A distinguished womn.  She has a lovely outfit, a proud carriage.</td>', 'A distinguished womn.  She has a lovely outfit, a proud carriage.', '2011-11-02 23:49:26.000000', NULL, 1),
(6583361, 981660, 30982, '<td valign="top">Wonderful light, lovely capture - makes me smile!</td>', 'Wonderful light, lovely capture - makes me smile!', '2011-11-02 23:51:16.000000', NULL, 1),
(6583362, 980379, 65234, '<td valign="top">Go, Ladybug!!  Hope she''s very hungry.</td>', 'Go, Ladybug!!  Hope she''s very hungry.', '2011-11-02 23:51:26.000000', NULL, 1),
(6583363, 981297, 30982, '<td valign="top">Excellent collection of textures and color!</td>', 'Excellent collection of textures and color!', '2011-11-02 23:51:34.000000', NULL, 1),
(6583364, 981637, 30982, '<td valign="top">Very graceful and statuesque!</td>', 'Very graceful and statuesque!', '2011-11-02 23:52:02.000000', NULL, 1),
(6583369, 981513, 30982, '<td valign="top">Indeed - and approaching with a rather serious look!  Beautiful light, gorgeous cat.  Not an angle we usually see.</td>', 'Indeed - and approaching with a rather serious look!  Beautiful light, gorgeous cat.  Not an angle we usually see.', '2011-11-02 23:58:43.000000', NULL, 1),
(6583370, 981132, 30982, '<td valign="top">LOL!  What an expression!!</td>', 'LOL!  What an expression!!', '2011-11-02 23:59:07.000000', NULL, 1),
(6583372, 981619, 30982, '<td valign="top">Wonderfully spontaneous and fun.  If this is "staged" you did a remarkable job of making it feel otherwise.  I even like all the parked cars - they way they are walking makes it all disappear!</td>', 'Wonderfully spontaneous and fun.  If this is "staged" you did a remarkable job of making it feel otherwise.  I even like all the parked cars - they way they are walking makes it all disappear!', '2011-11-03 00:00:14.000000', NULL, 1),
(6583375, 981644, 30982, '<td valign="top">No!  Don''t jump!  At least not until the trash the dress session!  Nice romantic feel - a bit of loss in the detail in the black suit, but what can you do with that?  They look ever so slightly tenuous - steadfast but just a wee bit tenous about the whole thing.</td>', 'No!  Don''t jump!  At least not until the trash the dress session!  Nice romantic feel - a bit of loss in the detail in the black suit, but what can you do with that?  They look ever so slightly tenuous - steadfast but just a wee bit tenous about the whole thing.', '2011-11-03 00:01:38.000000', NULL, 1),
(6583376, 981481, 30982, '<td valign="top">A lovely take on a not-so-commonly-shot "landscape".</td>', 'A lovely take on a not-so-commonly-shot "landscape".', '2011-11-03 00:02:40.000000', NULL, 1),
