(6584047, 981487, 124982, '<td valign="top">I love the composition, just watch the processing. The man has a nice halo around him. Also, the pink graduated filter (?) looks too unnatural. A lovely image though.</td>', 'I love the composition, just watch the processing. The man has a nice halo around him. Also, the pink graduated filter (?) looks too unnatural. A lovely image though.', '2011-11-03 20:32:27.000000', NULL, 1),
(6584049, 981608, 124982, '<td valign="top">Appropriate title. Lovely image, really enjoying the composition of this!</td>', 'Appropriate title. Lovely image, really enjoying the composition of this!', '2011-11-03 20:33:58.000000', NULL, 1),
(6584053, 979228, 51747, '<td valign="top">Would love to have both eyes in focus.</td>', 'Would love to have both eyes in focus.', '2011-11-03 20:36:13.000000', NULL, 1),
(6584057, 978213, 124982, '<td valign="top">Truly beautiful image. I think a much tighter crop would''ve helped draw the attention to the monkey, and really emphasize the details in the face and fur which is getting lost in the greenery right now.</td>', 'Truly beautiful image. I think a much tighter crop would''ve helped draw the attention to the monkey, and really emphasize the details in the face and fur which is getting lost in the greenery right now.', '2011-11-03 20:37:39.000000', NULL, 1),
(6584062, 981506, 124982, '<td valign="top">Wow. Wow. Wow. This is probably the nicest image of this genre I''ve seen in a long time. Very rare to see B&amp;W, and this just shines with the selective saturation of the exhaust. Just beautiful!</td>', 'Wow. Wow. Wow. This is probably the nicest image of this genre I''ve seen in a long time. Very rare to see B&W, and this just shines with the selective saturation of the exhaust. Just beautiful!', '2011-11-03 20:40:47.000000', NULL, 1),
(6584063, 981344, 124982, '<td valign="top">Lovely bird. Unfortunately I feel as though the focus is more on the back than the head/face which seem to be out of focus?</td>', 'Lovely bird. Unfortunately I feel as though the focus is more on the back than the head/face which seem to be out of focus?', '2011-11-03 20:41:49.000000', NULL, 1),
(6584065, 978634, 124982, '<td valign="top">Very elegantly composed and processed. Quite beautiful.</td>', 'Very elegantly composed and processed. Quite beautiful.', '2011-11-03 20:43:36.000000', NULL, 1),
