(6584076, 979517, 69324, '<td valign="top">Great tones and perspective.</td>', 'Great tones and perspective.', '2011-11-03 20:49:02.000000', NULL, 1),
(6584078, 979065, 124982, '<td valign="top">Lovely composition! Looks like a scene out of the Matrix. Love how the soft blue acts as a cushion between the two imposing, formidable buildings. The lamppost also serves as a great focal point.</td>', 'Lovely composition! Looks like a scene out of the Matrix. Love how the soft blue acts as a cushion between the two imposing, formidable buildings. The lamppost also serves as a great focal point.', '2011-11-03 20:49:42.000000', NULL, 1),
(6584079, 980805, 124982, '<td valign="top">I''m guessing this is a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=113156" rel="nofollow" target="_blank">jagar</a> image? If not, my apologies..but take it as a compliment. Lovely composition and very expertly processed. The tones and fairly muted colors are quite pleasing.</td>', 'I''m guessing this is a  jagar image? If not, my apologies..but take it as a compliment. Lovely composition and very expertly processed. The tones and fairly muted colors are quite pleasing.', '2011-11-03 20:51:24.000000', NULL, 1),
(6584080, 981365, 69324, '<td valign="top">Never seen a Cosmos that color, looks like you must of been wide open, nice.</td>', 'Never seen a Cosmos that color, looks like you must of been wide open, nice.', '2011-11-03 20:52:40.000000', NULL, 1),
