(6588304, 980599, 108069, '<td valign="top">Love the processing. Awesome scene and manipulation of the viewpoint on your subject.</td>', 'Love the processing. Awesome scene and manipulation of the viewpoint on your subject.', '2011-11-07 19:09:47.000000', NULL, 1),
(6588307, 981487, 108069, '<td valign="top">Powerful. Great motion, and awesome tones and clarity.</td>', 'Powerful. Great motion, and awesome tones and clarity.', '2011-11-07 19:10:21.000000', NULL, 1),
(6588308, 979665, 108069, '<td valign="top">Lovely photo. Composition is perfect. Well done on the foreground sharpness.</td>', 'Lovely photo. Composition is perfect. Well done on the foreground sharpness.', '2011-11-07 19:11:24.000000', NULL, 1),
(6588313, 979065, 108069, '<td valign="top">Awesome. Incredible tones in the buildings... well, throughout. Love the lamp, like an eye the viewer initially overlooks. Great lines. Love it.<br/> <br/>10 and a fav.</td>', 'Awesome. Incredible tones in the buildings... well, throughout. Love the lamp, like an eye the viewer initially overlooks. Great lines. Love it. 10 and a fav.', '2011-11-07 19:16:26.000000', NULL, 1),
(6588314, 981517, 108069, '<td valign="top">Great tones and muted colors. I love this.</td>', 'Great tones and muted colors. I love this.', '2011-11-07 19:16:37.000000', NULL, 1),
(6588315, 981507, 108069, '<td valign="top">Stunning capture. Beautiful.</td>', 'Stunning capture. Beautiful.', '2011-11-07 19:16:43.000000', NULL, 1),
(6588317, 980826, 108069, '<td valign="top">Wow. Incredible scene, awesome scale and tones and color. Awesome.</td>', 'Wow. Incredible scene, awesome scale and tones and color. Awesome.', '2011-11-07 19:16:55.000000', NULL, 1),
