INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6588319, 981297, 108069, '<td valign="top">Outstanding environmental portrait-type capture. Slice of very interesting life, with a twist in the background. Processing is super as well. Awesome shot.</td>', 'Outstanding environmental portrait-type capture. Slice of very interesting life, with a twist in the background. Processing is super as well. Awesome shot.', '2011-11-07 19:17:14.000000', NULL, 1),
(6588320, 981580, 108069, '<td valign="top">Great capture. Well seen scene.</td>', 'Great capture. Well seen scene.', '2011-11-07 19:17:19.000000', NULL, 1),
(6588321, 979867, 108069, '<td valign="top">Fantastic light. Rich tones, lovely mood. Superb.</td>', 'Fantastic light. Rich tones, lovely mood. Superb.', '2011-11-07 19:18:03.000000', NULL, 1),
(6588323, 981144, 19825, '<td valign="top">Very cool.</td>', 'Very cool.', '2011-11-07 19:24:50.000000', NULL, 1),
(6588324, 981489, 19825, '<td valign="top">Very retro.</td>', 'Very retro.', '2011-11-07 19:25:56.000000', NULL, 1),
(6588347, 981030, 59796, '<td valign="top">Delightful long exposure! Love the rock textures and moving clouds, both pointing to the long gone Sunset on the horizon. The creamy smooth water calming the fiery tones in the sky. Fabulous!</td>', 'Delightful long exposure! Love the rock textures and moving clouds, both pointing to the long gone Sunset on the horizon. The creamy smooth water calming the fiery tones in the sky. Fabulous!', '2011-11-07 19:40:54.000000', NULL, 1),
(6588356, 981057, 59796, '<td valign="top">What a wonderful pristine world! Looks prehistoric and the B/W conversion helps - I can see Pterodactyl''s flying out of the fog any second now :) Makes me wish I didn''t have severe vertigo, just so I can climb up mountains to witness this first hand. Love the shot!</td>', 'What a wonderful pristine world! Looks prehistoric and the B/W conversion helps - I can see Pterodactyl''s flying out of the fog any second now :) Makes me wish I didn''t have severe vertigo, just so I can climb up mountains to witness this first hand. Love the shot!', '2011-11-07 19:48:23.000000', NULL, 1),
(6588357, 978683, 59796, '<td valign="top">Love the simplicity, the lines, the complementary gold/blue colors, and the repetitive patterns. Good eye!</td>', 'Love the simplicity, the lines, the complementary gold/blue colors, and the repetitive patterns. Good eye!', '2011-11-07 19:49:39.000000', NULL, 1),
(6588375, 980439, 59796, '<td valign="top">but a fabulous ride! <br/>Love such lonely country roads across fall foliage. Beautiful! Not too keen on the speed limit board grabbing all the attention though.</td>', 'but a fabulous ride! Love such lonely country roads across fall foliage. Beautiful! Not too keen on the speed limit board grabbing all the attention though.', '2011-11-07 20:09:23.000000', NULL, 1),
(6588376, 981406, 59796, '<td valign="top">Bad hair day? :)<br/>Love the contrast of the Kingfisher''s cool blue against warm fall colors bokeh. And the bokeh is so smooth and lovely! Wonderful capture.</td>', 'Bad hair day? :)Love the contrast of the Kingfisher''s cool blue against warm fall colors bokeh. And the bokeh is so smooth and lovely! Wonderful capture.', '2011-11-07 20:10:38.000000', NULL, 1),
(6588377, 981319, 59796, '<td valign="top">Very nicely done! Love the soft color palette and the creamy bokeh! <br/>Feels a little unbalanced because of the asymmetrical negative space, but that''s the only nit I can pick after staring for a while.</td>', 'Very nicely done! Love the soft color palette and the creamy bokeh! Feels a little unbalanced because of the asymmetrical negative space, but that''s the only nit I can pick after staring for a while.', '2011-11-07 20:12:49.000000', NULL, 1),
(6588379, 981053, 59796, '<td valign="top">Love the gentle curve of the bank leading to the lighthouse. Nice, deep DOF. Love the crystal clear still water and the hint of fall colors. And the wonderful blue of the sky. Not too keep on the moon position, but you can''t move it can you :)</td>', 'Love the gentle curve of the bank leading to the lighthouse. Nice, deep DOF. Love the crystal clear still water and the hint of fall colors. And the wonderful blue of the sky. Not too keep on the moon position, but you can''t move it can you :)', '2011-11-07 20:15:52.000000', NULL, 1),
(6588381, 978726, 114285, '<td valign="top">Totally love it 10.</td>', 'Totally love it 10.', '2011-11-07 20:19:40.000000', NULL, 1),
(6588382, 979449, 97225, '<td valign="top">Nice capture. I know from experience that it is hard to get nice detail in their feathers. I like the repetition of the left facing swans, with the one renegade going the other way.</td>', 'Nice capture. I know from experience that it is hard to get nice detail in their feathers. I like the repetition of the left facing swans, with the one renegade going the other way.', '2011-11-07 20:20:23.000000', NULL, 1),
(6588383, 979228, 59796, '<td valign="top">Intense! Wonderful capture and title. The use of shallow DOF is interesting.</td>', 'Intense! Wonderful capture and title. The use of shallow DOF is interesting.', '2011-11-07 20:22:26.000000', NULL, 1),
(6588392, 981541, 59796, '<td valign="top">Rather ineffective camouflage :)<br/>Interesting presentation and a wonderful low-key capture.</td>', 'Rather ineffective camouflage :)Interesting presentation and a wonderful low-key capture.', '2011-11-07 20:27:14.000000', NULL, 1),
(6588395, 979865, 59796, '<td valign="top">Scary scene alright! Nice B/W conversion and love the textures and patterns on the water, the rocks, the bridge and the sky. <br/>Compositionally, all the lines seem to be leading up to the base of that building in the center - which seems like a reluctant subject. Not too sure about that.</td>', 'Scary scene alright! Nice B/W conversion and love the textures and patterns on the water, the rocks, the bridge and the sky. Compositionally, all the lines seem to be leading up to the base of that building in the center - which seems like a reluctant subject. Not too sure about that.', '2011-11-07 20:29:40.000000', NULL, 1),
(6588399, 981657, 59796, '<td valign="top">Always wanted to capture something like this, but was never successful. Wonderful depiction of fall. The nice contrasting green of the background helps.</td>', 'Always wanted to capture something like this, but was never successful. Wonderful depiction of fall. The nice contrasting green of the background helps.', '2011-11-07 20:31:34.000000', NULL, 1),
