(6588470, 981293, 59796, '<td valign="top">Oh so beautiful! Love the fiery reds and yellows contrasting with the cool sky blue. Amazing job shooting into the sun and preserving all the details.</td>', 'Oh so beautiful! Love the fiery reds and yellows contrasting with the cool sky blue. Amazing job shooting into the sun and preserving all the details.', '2011-11-07 21:02:57.000000', NULL, 1),
(6588479, 981017, 59796, '<td valign="top">Wonderful! Almost abstract. The hint of fall colors, and the hint of a boat - lets your imagination soar. And delightfully under-processed. Very nice!</td>', 'Wonderful! Almost abstract. The hint of fall colors, and the hint of a boat - lets your imagination soar. And delightfully under-processed. Very nice!', '2011-11-07 21:07:07.000000', NULL, 1),
(6588482, 981064, 59796, '<td valign="top">Must''ve been hard getting to this spot amidst all that snow. Definitely worth it though - love the shades of white and blue dominating greens and browns. A quiet and intensely beautiful setting.</td>', 'Must''ve been hard getting to this spot amidst all that snow. Definitely worth it though - love the shades of white and blue dominating greens and browns. A quiet and intensely beautiful setting.', '2011-11-07 21:08:53.000000', NULL, 1),
(6588487, 978322, 59796, '<td valign="top">Beautiful rock bridge! The warm fall colors complement the cool sky blue nicely. Such still water begs a complete reflection though :( Wish the trees weren''t cutoff in the reflection.</td>', 'Beautiful rock bridge! The warm fall colors complement the cool sky blue nicely. Such still water begs a complete reflection though :( Wish the trees weren''t cutoff in the reflection.', '2011-11-07 21:12:50.000000', NULL, 1),
(6588490, 980904, 59796, '<td valign="top">Wow! The stunning muted color of the water, the patterns on the sand, the bubbles rising up, the light fall off and vignetting - all complement the insane activity :) Very nicely done!</td>', 'Wow! The stunning muted color of the water, the patterns on the sand, the bubbles rising up, the light fall off and vignetting - all complement the insane activity :) Very nicely done!', '2011-11-07 21:15:20.000000', NULL, 1),
(6588492, 980823, 59796, '<td valign="top">Wow! The beautiful pastel colors are out of this world! Love the dutch windmills and landscapes. Such wonderful long exposure!</td>', 'Wow! The beautiful pastel colors are out of this world! Love the dutch windmills and landscapes. Such wonderful long exposure!', '2011-11-07 21:17:10.000000', NULL, 1),
(6588493, 981097, 30214, '<td valign="top">beautiful portrait, very Avedon!</td>', 'beautiful portrait, very Avedon!', '2011-11-07 21:17:57.000000', NULL, 1),
(6588505, 980738, 59796, '<td valign="top">Interesting framing that I hadn''t seen before. Nice balance of exposure between sky and fair lights. Love the blue and gold complementary colors.</td>', 'Interesting framing that I hadn''t seen before. Nice balance of exposure between sky and fair lights. Love the blue and gold complementary colors.', '2011-11-07 21:25:24.000000', NULL, 1),
(6588511, 979065, 59796, '<td valign="top">As minimalistic as urban landscape gets. Love the cool blue and desaturated concrete.</td>', 'As minimalistic as urban landscape gets. Love the cool blue and desaturated concrete.', '2011-11-07 21:26:23.000000', NULL, 1),
(6588517, 981608, 59796, '<td valign="top">Love the cork-screw! Seems ready to drill into the sky! Wonderful sub patterns too.</td>', 'Love the cork-screw! Seems ready to drill into the sky! Wonderful sub patterns too.', '2011-11-07 21:28:07.000000', NULL, 1),
(6588539, 979347, 59796, '<td valign="top">Wow! Lovely grove of trees supported by the colorful plants in the foreground. Wonderfully moody clouds complement the scene. Nice depiction of Autumn. Don''t quite get the title though...</td>', 'Wow! Lovely grove of trees supported by the colorful plants in the foreground. Wonderfully moody clouds complement the scene. Nice depiction of Autumn. Don''t quite get the title though...', '2011-11-07 21:35:38.000000', NULL, 1),
